    acc = stwo_qm31_add(acc, stwo_qm31_mul(e55, stwo_load_qm31(random_coeff_powers, rc_base + 51u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e57, stwo_load_qm31(random_coeff_powers, rc_base + 52u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e45, stwo_load_qm31(random_coeff_powers, rc_base + 53u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e61, stwo_load_qm31(random_coeff_powers, rc_base + 54u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e63, stwo_load_qm31(random_coeff_powers, rc_base + 55u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e65, stwo_load_qm31(random_coeff_powers, rc_base + 56u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e67, stwo_load_qm31(random_coeff_powers, rc_base + 57u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e69, stwo_load_qm31(random_coeff_powers, rc_base + 58u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e71, stwo_load_qm31(random_coeff_powers, rc_base + 59u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e73, stwo_load_qm31(random_coeff_powers, rc_base + 60u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e75, stwo_load_qm31(random_coeff_powers, rc_base + 61u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e77, stwo_load_qm31(random_coeff_powers, rc_base + 62u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e79, stwo_load_qm31(random_coeff_powers, rc_base + 63u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e81, stwo_load_qm31(random_coeff_powers, rc_base + 64u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e83, stwo_load_qm31(random_coeff_powers, rc_base + 65u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e85, stwo_load_qm31(random_coeff_powers, rc_base + 66u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e59, stwo_load_qm31(random_coeff_powers, rc_base + 67u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e89, stwo_load_qm31(random_coeff_powers, rc_base + 68u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e91, stwo_load_qm31(random_coeff_powers, rc_base + 69u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e93, stwo_load_qm31(random_coeff_powers, rc_base + 70u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e95, stwo_load_qm31(random_coeff_powers, rc_base + 71u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e97, stwo_load_qm31(random_coeff_powers, rc_base + 72u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e99, stwo_load_qm31(random_coeff_powers, rc_base + 73u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e87, stwo_load_qm31(random_coeff_powers, rc_base + 74u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e103, stwo_load_qm31(random_coeff_powers, rc_base + 75u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e105, stwo_load_qm31(random_coeff_powers, rc_base + 76u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e107, stwo_load_qm31(random_coeff_powers, rc_base + 77u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e111, stwo_load_qm31(random_coeff_powers, rc_base + 78u)));
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e115, stwo_load_qm31(random_coeff_powers, rc_base + 79u)));
